applied = 0
for idx, (old, new) in enumerate(PATCHES, 1):
    n = src.count(old)
    if n == 1:
        src = src.replace(old, new, 1); applied += 1
    elif n == 0:
        print(f"  ! #{idx} SKIP — 대상 없음(이미 적용?)")
    else:
        print(f"  ! #{idx} SKIP — {n}회 중복, 수동확인 필요")

open(TARGET, "w", encoding="utf-8").write(src)
print(f"적용 완료: {applied}/{len(PATCHES)} patches")

