    j = J()
    assert "trl_pathway" in j.WEIGHTS
    assert "alignment" in j.WEIGHTS_V1
    assert "patent_map_enabled" not in j.JUDGE_SYSTEM_PROMPT
    assert "0.25 * timing_accuracy" in inspect.getsource(BackTestEvaluator.run)
    print("LLM V2 axes:", list(j.WEIGHTS.keys()))
    print("V1 preserved:", list(j.WEIGHTS_V1.keys()))
